function sum(p){ return p.x + p.y; }
function bench(make){ let acc=0; const t=Date.now(); for(let i=0;i<5e6;i++){ acc += sum(make(i)); } return {acc, ms: Date.now()-t}; }
// monomorphic: every object same hidden class, same number type
const mono = bench(i => ({x: i|0, y: (i+1)|0}));
// polymorphic: alternating shape + mixed int/double
const poly = bench(i => i%2 ? {x: i, y: i+0.5} : {y: i, x: i+0.5, tag: 1});
console.log('mono_ms=' + mono.ms);
console.log('poly_ms=' + poly.ms);
console.log('mono_faster=' + (mono.ms <= poly.ms));
